mapper.select:
SELECT a.id, a.asset_code, a.name, a.category_id, c.name AS category_name, a.brand_model, a.purpose, a.department_id, a.department_name, a.current_user_id, u.real_name AS current_user_name, a.status, a.purchase_amount, a.purchase_date, a.source_type, a.remark FROM asset a LEFT JOIN asset_category c ON a.category_id = c.id AND c.is_deleted = 0 LEFT JOIN user u ON a.current_user_id = u.id AND u.is_deleted = 0 WHERE a.is_deleted = 0
AND a.current_user_id = #{currentUserId}
AND a.department_id = #{departmentId}
AND a.name LIKE CONCAT('%', #{name}, '%')
AND a.asset_code LIKE CONCAT(#{assetCode}, '%')
AND a.brand_model LIKE CONCAT('%', #{brandModel}, '%')
AND u.real_name LIKE CONCAT('%', #{realName}, '%')
AND a.status = #{assetStatus}
AND c.name LIKE CONCAT('%', #{categoryName}, '%')
AND a.department_name LIKE CONCAT('%', #{departmentName}, '%')
AND a.source_type = #{sourceType}
AND a.purchase_date >= #{purchaseDateStart}
AND a.purchase_date <= #{purchaseDateEnd}
ORDER BY a.id DESC
